CREATE SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;
CREATE ROLE anon;
CREATE ROLE authenticated;
CREATE ROLE service_role;
CREATE SCHEMA auth;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.jwt.claim.sub', true), '')::uuid $$;
CREATE TABLE public.departments(id uuid PRIMARY KEY, code text NOT NULL UNIQUE, is_active boolean NOT NULL DEFAULT true);
CREATE TABLE public.employees(id uuid PRIMARY KEY, user_id uuid UNIQUE NOT NULL, employment_status text NOT NULL CHECK (employment_status IN ('INVITED','ACTIVE','SUSPENDED','EXITED')));
CREATE TABLE public.employee_departments(employee_id uuid NOT NULL REFERENCES public.employees(id), department_id uuid NOT NULL REFERENCES public.departments(id), PRIMARY KEY(employee_id, department_id));
CREATE TABLE public.projects(id uuid PRIMARY KEY, status text NOT NULL CHECK(status IN ('active','archived')));
CREATE TABLE public.project_team_members(project_id uuid NOT NULL REFERENCES public.projects(id), employee_id uuid NOT NULL REFERENCES public.employees(id), PRIMARY KEY(project_id, employee_id));
CREATE TABLE public.customers(id uuid PRIMARY KEY);
CREATE TABLE public.sales_opportunities(id uuid PRIMARY KEY, customer_id uuid NOT NULL REFERENCES public.customers(id));
CREATE TABLE public.customer_requirements(id uuid PRIMARY KEY, opportunity_id uuid NOT NULL REFERENCES public.sales_opportunities(id), customer_id uuid NOT NULL REFERENCES public.customers(id));
CREATE TABLE public.requirement_baselines(id uuid PRIMARY KEY, requirement_id uuid NOT NULL REFERENCES public.customer_requirements(id));
CREATE TABLE public.sales_project_handovers(id uuid PRIMARY KEY, baseline_id uuid NOT NULL REFERENCES public.requirement_baselines(id), project_id uuid NOT NULL REFERENCES public.projects(id), status text NOT NULL);
CREATE TABLE public.department_process_templates(id uuid PRIMARY KEY, department_id uuid NOT NULL REFERENCES public.departments(id), template_key text NOT NULL, version integer NOT NULL CHECK(version > 0), status text NOT NULL CHECK(status IN ('DRAFT','ACTIVE','RETIRED')), active_document_revision_id uuid NULL, UNIQUE(department_id,template_key,version));
CREATE TABLE public.department_process_template_document_revisions(id uuid PRIMARY KEY, template_id uuid NOT NULL REFERENCES public.department_process_templates(id), revision_number integer NOT NULL CHECK(revision_number > 0), content text NOT NULL, content_sha256 text NOT NULL, UNIQUE(template_id,id));
ALTER TABLE public.department_process_templates ADD CONSTRAINT template_active_revision_fkey FOREIGN KEY(id,active_document_revision_id) REFERENCES public.department_process_template_document_revisions(template_id,id);
CREATE TABLE public.permission_test_grants(user_id uuid NOT NULL, permission_key text NOT NULL, PRIMARY KEY(user_id, permission_key));
CREATE FUNCTION public.has_any_permission(p_user uuid, p_keys text[]) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT EXISTS (SELECT 1 FROM public.permission_test_grants WHERE user_id=p_user AND permission_key=ANY(p_keys)) $$;
CREATE FUNCTION public.can_access_department_drive(p_user uuid, p_department uuid, p_project uuid) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT EXISTS (SELECT 1 FROM public.employees e JOIN public.employee_departments ed ON ed.employee_id=e.id WHERE e.user_id=p_user AND e.employment_status='ACTIVE' AND ed.department_id=p_department) $$;
CREATE FUNCTION public.lifecycle_actor() RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v uuid:=auth.uid(); BEGIN IF v IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; RETURN v; END; $$;
CREATE FUNCTION public.lifecycle_can_manage_department(p_actor uuid,p_department uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.can_access_department_drive(p_actor,p_department,NULL) AND public.has_any_permission(p_actor,ARRAY['projects.manage','engineering.manage','documents.edit']) $$;
